#!/usr/bin/env python3
"""Turns the fonts in assets/fonts into src/app/embedded_fonts.h so the
game is a single self-contained executable. Run from the project folder:
    python3 tools/embed_fonts.py
"""
import pathlib

FONTS = [
    ("FONT_DISPLAY", "Orbitron-Bold.ttf"),
    ("FONT_BODY", "Rajdhani-SemiBold.ttf"),
    ("FONT_MONO", "ShareTechMono-Regular.ttf"),
]

root = pathlib.Path(__file__).resolve().parent.parent
lines = [
    "// embedded_fonts.h - GENERATED by tools/embed_fonts.py, do not edit by hand.",
    "// Fonts are licensed under the SIL Open Font License (see assets/fonts).",
    "#ifndef EMBEDDED_FONTS_H",
    "#define EMBEDDED_FONTS_H",
    "",
]
for name, file_name in FONTS:
    data = (root / "assets" / "fonts" / file_name).read_bytes()
    lines.append(f"// {file_name}")
    lines.append(f"static const unsigned char {name}_DATA[{len(data)}] = {{")
    for i in range(0, len(data), 20):
        lines.append("    " + ", ".join(str(b) for b in data[i:i + 20]) + ",")
    lines.append("};")
    lines.append(f"static const int {name}_SIZE = {len(data)};")
    lines.append("")
lines.append("#endif // EMBEDDED_FONTS_H")
(root / "src" / "app" / "embedded_fonts.h").write_text("\n".join(lines) + "\n")
print("wrote src/app/embedded_fonts.h")
